/// Γ on native-numeral words: interlace two canonical `encode` outputs and
/// return another canonical `encode` output.
pub fn interlace_words(p_word: &str, q_word: &str) -> Result<String, &'static str> {
    let p = canonical_encode_bits(p_word)?;
    let q = canonical_encode_bits(q_word)?;
    let width = p.len().max(q.len());

    let mut merged = Vec::with_capacity(width * 2);
    for k in 0..width {
        merged.push(p.get(k).copied().unwrap_or(false));
        merged.push(q.get(k).copied().unwrap_or(false));
    }
    Ok(encode_bits_canonical(&merged))
}

/// Λ on a native-numeral word: split one canonical `encode` output into its
/// even/odd cell lanes and return two canonical `encode` outputs.
pub fn deinterlace_word(word: &str) -> Result<(String, String), &'static str> {
    let bits = canonical_encode_bits(word)?;
    let mut p = Vec::with_capacity((bits.len() + 1) / 2);
    let mut q = Vec::with_capacity(bits.len() / 2);

    for (i, bit) in bits.into_iter().enumerate() {
        if i % 2 == 0 { p.push(bit); } else { q.push(bit); }
    }

    Ok((encode_bits_canonical(&p), encode_bits_canonical(&q)))
}

/// End-to-end syzygy invariant for the native numeral factor diagram.
///
/// This is deliberately stronger than checking either `p*q == N` or
/// `Λ(Γ(P,Q)) == (P,Q)` by itself.  All four stages must live in the same
/// canonical `encode()` representation and the whole diagram must commute:
///
///   W_N = encode(N)
///   W_p = encode(p), W_q = encode(q)
///   D   = Γ(W_p, W_q)
///   Λ(D) = (W_p, W_q)
///   encode( μ(Λ(D)) ) = W_N,  where μ is the native word multiplication.
///
/// `Γ(Λ(D)) == D` is checked as well, so both directions of the interlace
/// are required to preserve the same canonical word rather than merely its
/// decoded integer.
pub fn syzygy_preserves(n: &BigUint, p: &BigUint, q: &BigUint) -> bool {
    // μ must close on the parent before any representation claim is made.
    if multiply_via_word(p, q) != *n {
        return false;
    }

    let n_word = encode_biguint(n);
    let p_word = encode_biguint(p);
    let q_word = encode_biguint(q);

    // Every participant is required to be canonical encode output.
    if canonical_encode_bits(&n_word).is_err()
        || canonical_encode_bits(&p_word).is_err()
        || canonical_encode_bits(&q_word).is_err()
    {
        return false;
    }

    let d = match interlace_words(&p_word, &q_word) {
        Ok(w) => w,
        Err(_) => return false,
    };

