///
/// Missing high cells are zero (`⊤`) while the other lane still has magnitude.
/// The result is canonicalized exactly as `encode` would canonicalize a value:
/// trailing high zero cells are omitted.  Λ is the inverse: even cells go to P,
/// odd cells go to Q, and each lane is canonicalized back to an `encode` word.

/// Parse only a canonical word produced by `encode`.
///
/// `decode` deliberately accepts the structural shape; the extra re-encode
/// equality here rejects non-canonical words with redundant high zero cells so
/// interlace/deinterlace really operate on *the output type of encode*.
fn canonical_encode_bits(word: &str) -> Result<Vec<bool>, &'static str> {
    let n = decode(word).ok_or("expected a native_numeral encode word")?;
    if encode_biguint(&n) != word {
        return Err("word is structurally decodable but is not canonical encode output");
    }
    Ok(to_bits_low_first(&n))
}

/// Build exactly the same word shape as `encode` from LSB-first bits.
/// High zero padding is discarded, just as `BigUint`/`encode` discard it.
fn encode_bits_canonical(bits: &[bool]) -> String {
    let mut end = bits.len();
    while end > 0 && !bits[end - 1] { end -= 1; }

    if end == 0 {
        return String::from("⊢⊙⊡⊣");
    }

    let mut w = String::new();
    w.push('⊢');
    for &bit in &bits[..end] {
        w.push('≻');
        w.push('⋈');
        w.push('∈');
        w.push(if bit { '⊥' } else { '⊤' });
        w.push('∋');
    }
    w.push('⊙');
    w.push('⊡');
    w.push('⊣');
    w
}

