259	/// One core bead fanned to f arms via f−1 chained FSPLITs; each arm is a strand.
260	fn star(core: Token, arms: &[Vec<Token>]) -> Graph {
261	    let mut g = Graph::new();
262	    let hub = g.add(core);
263	    let f = arms.len();
264	    let fan: Vec<usize> = (0..f.saturating_sub(1)).map(|_| g.add(Token::Fsplit)).collect();
265	    let mut prev = hub;
266	    for &fid in &fan {
267	        g.connect(prev, fid);
268	        prev = fid;
269	    }
270	    // out-slots to hang arms on: each split contributes one, the last split a second
271	    let mut slots: Vec<usize> = Vec::new();
272	    if fan.is_empty() {
273	        slots.push(hub);
274	    } else {
275	        slots.extend(fan.iter().copied());
276	        slots.push(*fan.last().unwrap());
277	    }
278	    for (i, body) in arms.iter().enumerate() {
279	        let anchor = *slots.get(i).unwrap_or_else(|| slots.last().unwrap());
280	        let arm = g.chain_of(body);
281	        if let Some(&first) = arm.first() {
282	            g.connect(anchor, first);
283	        }
284	    }
285	    g
286	}
