288	/// pre → FSPLIT →(a | b)→ FFUSE → post: the reconverging series-parallel bubble.
289	fn bubble(pre: &[Token], a: &[Token], b: &[Token], post: &[Token]) -> Graph {
290	    let mut g = Graph::new();
