        let p = (*pos).min(spine.len() - 1);
        let node = spine[p];
        let after = g.successors(node);
        let fid = g.add(Token::Fsplit);
        g.edges.retain(|&(x, y)| !(x == node && after.contains(&y)));
        g.connect(node, fid);
        for nxt in after {
            g.connect(fid, nxt);
