        crate::expand_user("~/imsgct/MoDoT/ob3ects/primitives"),
        crate::expand_user("~/imsgct/MoDoT/ob3ects"),
    ];
    let mut path = None;
    for r in &roots {
        let cand = std::path::Path::new(r)
            .join(format!("the_primitive_type_called_{key}_ob3ect.json"));
        if cand.is_file() {
            path = Some(cand);
            break;
        }
    }
    let Some(path) = path else {
