1167	pub(crate) fn isqrt(n: &BigUint) -> BigUint {
1168	    if n.is_zero() {
1169	        return BigUint::zero();
1170	    }
1171	    let two = BigUint::from(2u32);
1172	    let one = BigUint::from(1u32);
1173	    let mut x = pow2((n.bits() as usize) / 2 + 1);
1174	    loop {
1175	        // Newton's own step, x -> (x + n/x)/2, is three word operations: a
1176	        // division to get n/x, an addition, and a division by two. x is
1177	        // never zero through this loop (it starts at a positive power of
1178	        // two and the iteration only produces smaller positive values on
1179	        // the way down to the true root), so the unwraps are safe.
1180	        let (q, _) = divmod_via_word(n, &x).unwrap();
1181	        let y = divmod_via_word(&add_via_word(&x, &q), &two).unwrap().0;
1182	        if y >= x {
1183	            break;
1184	        }
1185	        x = y;
1186	    }
1187	    while multiply_via_word(&x, &x) > *n {
1188	        x = subtract_via_word(&x, &one).unwrap();
1189	    }
1190	    x
