1	//! Factoring over IMASM numeral tapes.
2	//!
3	//! A numeral is never decoded into a machine integer.  Its payload is a tape
4	//! of EVALT/EVALF marks, least significant cell first.  Arithmetic consumes
5	//! and produces those tapes through the full-adder/full-subtractor tables.
6	
7	use crate::vox::{AREV, AFWD, CLINK, EVALF, EVALT, FFUSE, FSPLIT, IFIX, IMSCRIB, TANCH, VINIT};
8	use alloc::format;
9	use alloc::string::String;
10	use alloc::vec;
11	use alloc::vec::Vec;
12	
13	type Tape = Vec<char>;
14	
15	const PHASE: &[char] = &[VINIT, FSPLIT, AFWD, EVALT, EVALF, FFUSE, TANCH];
16	const ARITHMETIC: &[char] = &[VINIT, FSPLIT, CLINK, EVALT, EVALF, FFUSE, TANCH];
17	const BRANCH: &[char] = &[VINIT, FSPLIT, EVALT, EVALF, FFUSE, TANCH];
18	const SELECT: &[char] = &[VINIT, FSPLIT, IMSCRIB, FFUSE, TANCH];
19	const CONTINUE: &[char] = &[VINIT, AFWD, CLINK, TANCH];
20	const FIX: &[char] = &[VINIT, IMSCRIB, IFIX, TANCH];
21	
22	fn bit(mark: char) -> Result<bool, String> {
23	    match mark {
24	        EVALT => Ok(false),
25	        EVALF => Ok(true),
26	        _ => Err(format!("non-numeral mark {mark}")),
27	    }
28	}
29	
30	fn mark(v: bool) -> char {
31	    if v {
32	        EVALF
33	    } else {
34	        EVALT
35	    }
36	}
37	
38	fn trim(mut a: Tape) -> Tape {
39	    while a.len() > 1 && a.last() == Some(&EVALT) {
40	        a.pop();
41	    }
42	    if a.is_empty() {
43	        a.push(EVALT);
44	    }
45	    a
46	}
47	
48	pub fn parse_numeral(word: &str) -> Result<Tape, String> {
49	    let c: Vec<char> = word.chars().collect();
50	    if c == [VINIT, IMSCRIB, IFIX, TANCH] {
51	        return Ok(vec![EVALT]);
52	    }
53	
54	    // Properly-nested single-frame numeral: ⊢ ∈ [⊤/⊥ bits LSB-first] ≺ ∋ ⊡ ⊣
55	    // Entry ∈ and exit ∋ are the SAME frame; AREV ≺ sits INSIDE the frame so the
56	    // deposited marks bank and survive the reversal — the matched puncture.
57	    if c.len() >= 6
58	        && c.first() == Some(&VINIT)
59	        && c[1] == FSPLIT
60	        && c[c.len() - 1] == TANCH
61	        && c[c.len() - 2] == IFIX
62	        && c[c.len() - 3] == FFUSE
63	        && c[c.len() - 4] == AREV
64	    {
65	        let mut out = Vec::new();
66	        for &m in &c[2..c.len() - 4] {
67	            bit(m)?;
68	            out.push(m);
69	        }
70	        return Ok(trim(out));
71	    }
72	    if c.len() < 9 || c.first() != Some(&VINIT) || c[c.len() - 3..] != [IMSCRIB, IFIX, TANCH] {
73	        return Err("expected a native IMASM numeral word".into());
74	    }
75	    let body = &c[1..c.len() - 3];
76	    if body.len() % 5 != 0 {
77	        return Err("broken native numeral cell".into());
78	    }
79	    let mut out = Vec::with_capacity(body.len() / 5);
80	    for cell in body.chunks(5) {
81	        if cell[0] != AFWD || cell[1] != CLINK || cell[2] != FSPLIT || cell[4] != FFUSE {
82	            return Err("broken native numeral cell".into());
83	        }
84	        bit(cell[3])?;
85	        out.push(cell[3]);
86	    }
87	    Ok(trim(out))
88	}
89	
90	pub fn emit_numeral(tape: &[char]) -> String {
91	    if tape.len() == 1 && tape[0] == EVALT {
92	        return [VINIT, IMSCRIB, IFIX, TANCH].iter().collect();
93	    }
94	    let mut out = String::new();
95	    out.push(VINIT);
96	    for &b in tape {
97	        out.extend([AFWD, CLINK, FSPLIT, b, FFUSE]);
98	    }
99	    out.extend([IMSCRIB, IFIX, TANCH]);
100	    out
101	}
102	
103	fn cmp(a: &[char], b: &[char]) -> core::cmp::Ordering {
104	    let a = trim(a.to_vec());
105	    let b = trim(b.to_vec());
106	    if a.len() != b.len() {
107	        return a.len().cmp(&b.len());
108	    }
109	    for i in (0..a.len()).rev() {
110	        if a[i] != b[i] {
111	            return bit(a[i]).unwrap().cmp(&bit(b[i]).unwrap());
112	        }
113	    }
114	    core::cmp::Ordering::Equal
115	}
116	
117	fn add(a: &[char], b: &[char]) -> Tape {
118	    let mut out = Vec::new();
119	    let mut carry = false;
120	    for i in 0..a.len().max(b.len()) {
121	        let x = a
122	            .get(i)
123	            .copied()
124	            .map(bit)
125	            .transpose()
126	            .unwrap()
127	            .unwrap_or(false);
128	        let y = b
129	            .get(i)
130	            .copied()
131	            .map(bit)
132	            .transpose()
133	            .unwrap()
134	            .unwrap_or(false);
135	        out.push(mark(x ^ y ^ carry));
136	        carry = (x && y) || (x && carry) || (y && carry);
137	    }
138	    if carry {
139	        out.push(EVALF);
140	    }
141	    trim(out)
142	}
143	
144	fn sub(a: &[char], b: &[char]) -> Tape {
145	    let mut out = Vec::new();
146	    let mut borrow = false;
147	    for i in 0..a.len() {
148	        let x = bit(a[i]).unwrap();
149	        let y = b
150	            .get(i)
151	            .copied()
152	            .map(bit)
153	            .transpose()
154	            .unwrap()
155	            .unwrap_or(false);
156	        out.push(mark(x ^ y ^ borrow));
157	        borrow = (!x && (y || borrow)) || (y && borrow);
158	    }
159	    trim(out)
160	}
161	
162	fn mul(a: &[char], b: &[char]) -> Tape {
163	    let mut acc = vec![EVALT];
164	    for (i, &m) in b.iter().enumerate() {
165	        if bit(m).unwrap() {
166	            let mut row = vec![EVALT; i];
167	            row.extend_from_slice(a);
168	            acc = add(&acc, &row);
169	        }
170	    }
171	    trim(acc)
172	}
173	
174	fn divmod(n: &[char], d: &[char]) -> (Tape, Tape) {
175	    let mut q = vec![EVALT; n.len()];
176	    let mut r = vec![EVALT];
177	    for i in (0..n.len()).rev() {
178	        r.insert(0, n[i]);
179	        r = trim(r);
180	        if cmp(&r, d) != core::cmp::Ordering::Less {
181	            r = sub(&r, d);
182	            q[i] = EVALF;
183	        }
184	    }
185	    (trim(q), trim(r))
186	}
187	
188	fn modulo(n: &[char], d: &[char]) -> Tape {
189	    divmod(n, d).1
190	}
191	
192	fn mod_add(a: &[char], b: &[char], n: &[char]) -> Tape {
193	    modulo(&add(a, b), n)
194	}
195	
196	fn mod_mul(a: &[char], b: &[char], n: &[char]) -> Tape {
197	    modulo(&mul(a, b), n)
198	}
199	
200	fn abs_diff(a: &[char], b: &[char]) -> Tape {
201	    if cmp(a, b) == core::cmp::Ordering::Less {
202	        sub(b, a)
203	    } else {
204	        sub(a, b)
205	    }
206	}
