2	//! ParaASM — Practical Paraconsistent Universal Engine
3	//! Port of priests-engine/para_vm.py + imscribing_grammar/para/para_vm.py
4	//! Belnap FOUR VM with 19-instruction ISA, assembler, dialetheic alignment,
5	//! measurement sequence algebra, and IG snapshot bridge.
6	
7	use alloc::collections::BTreeMap;
8	use alloc::format;
9	use alloc::string::String;
10	use alloc::vec::Vec;
11	use crate::belnap::B4;
12	
13	// ── ParaASM instruction set ─────────────────────────────────────────
14	
15	/// The 19-instruction ParaASM ISA.
16	/// Frobenius core (4), register ops (2), control flow (8), stack (2), I/O (2).
17	#[derive(Clone, Debug, PartialEq)]
18	pub enum ParaAsm {
19	    // ── Frobenius core (mirrors 4 of 12 IMASM tokens) ──
20	    ENGAGR(u8),              // Engage Both — register → paradox
