1	//! Native numeral carry/fuse closure
2	//!
3	//! Grammar object:
4	//!     D(N) = ⊢ (≻⋈∈s₀∋)(≻⋈∈s₁∋)...(≻⋈∈sₖ∋) ⊙⊡⊣
5	//! where sᵢ ∈ {⊤, ⊥}.
6	//!
7	//! This module does not construct factors by arithmetic division.  It exposes
8	//! the grammar steps needed by `native_numeral factor`:
9	//!   1. parse/extract the payload mark stream,
10	//!   2. expose raw unbraid lanes,
11	//!   3. close candidate lanes through carry/fuse,
12	//!   4. accept only if the fused payload equals the target payload.
13	
14	const VINIT: char = '⊢';
15	const TANCH: char = '⊣';
16	const AFWD: char = '≻';
17	const CLINK: char = '⋈';
18	const FSPLIT: char = '∈';
19	const FFUSE: char = '∋';
20	const EVALT: char = '⊤'; // empty / zero mark in the native payload
21	const EVALF: char = '⊥'; // occupied / one mark in the native payload
22	const IMSCRIB: char = '⊙';
23	const IFIX: char = '⊡';
24	
25	#[derive(Clone, Debug)]
26	pub struct CarryColumn {
27	    pub k: usize,
28	    pub contributions: u64,
29	    pub carry_in: u64,
30	    pub output_mark: char,
31	    pub carry_out: u64,
32	}
33	
34	#[derive(Clone, Debug)]
35	pub struct CarryFuseReport {
36	    pub left: String,
37	    pub right: String,
38	    pub payload: String,
39	    pub columns: Vec<CarryColumn>,
40	}
41	
42	fn bit_from_mark(c: char) -> Result<u8, String> {
43	    match c {
44	        EVALT => Ok(0),
45	        EVALF => Ok(1),
46	        _ => Err(format!("bad native numeral mark: {c}")),
47	    }
48	}
49	
50	fn mark_from_bit(b: u8) -> Result<char, String> {
51	    match b {
52	        0 => Ok(EVALT),
53	        1 => Ok(EVALF),
54	        _ => Err(format!("bad bit: {b}")),
55	    }
56	}
57	
58	pub fn trim_high_empty(s: &str) -> String {
59	    let mut v: Vec<char> = s.chars().collect();
60	    while v.len() > 1 && v.last() == Some(&EVALT) {
61	        v.pop();
62	    }
63	    if v.is_empty() { v.push(EVALT); }
64	    v.into_iter().collect()
65	}
66	
67	pub fn word_from_marks(marks: &str) -> Result<String, String> {
68	    let mut out = String::new();
69	    out.push(VINIT);
70	    for mark in marks.chars() {
71	        bit_from_mark(mark)?;
72	        out.push(AFWD);
73	        out.push(CLINK);
74	        out.push(FSPLIT);
75	        out.push(mark);
76	        out.push(FFUSE);
77	    }
78	    out.push(IMSCRIB);
79	    out.push(IFIX);
80	    out.push(TANCH);
81	    Ok(out)
82	}
83	
84	pub fn extract_mark_stream(word: &str) -> Result<String, String> {
85	    let chars: Vec<char> = word.chars().filter(|c| !c.is_whitespace()).collect();
86	    if chars.first() != Some(&VINIT) {
87	        return Err("native numeral word must start with ⊢".to_string());
88	    }
89	    if chars.len() < 4 || chars[chars.len() - 3..] != [IMSCRIB, IFIX, TANCH] {
90	        return Err("native numeral word must close with ⊙⊡⊣".to_string());
91	    }
92	    let mut marks = String::new();
93	    let mut i = 1usize;
94	    let stop = chars.len() - 3;
95	    while i < stop {
96	        if i + 4 >= stop + 1 {
97	            return Err(format!("truncated cell at glyph offset {i}"));
98	        }
99	        if chars[i] != AFWD || chars[i + 1] != CLINK || chars[i + 2] != FSPLIT {
100	            return Err(format!("bad cell prefix at glyph offset {i}"));
101	        }
102	        let mark = chars[i + 3];
103	        bit_from_mark(mark)?;
104	        if chars[i + 4] != FFUSE {
105	            return Err(format!("bad cell suffix after glyph offset {}", i + 3));
106	        }
107	        marks.push(mark);
108	        i += 5;
109	    }
110	    Ok(marks)
111	}
112	
113	pub fn raw_unbraid(marks: &str, a_first: bool) -> (String, String) {
114	    let mut odd = String::new();
115	    let mut even = String::new();
116	    for (i, ch) in marks.chars().enumerate() {
117	        if i % 2 == 0 { odd.push(ch); } else { even.push(ch); }
118	    }
119	    if a_first { (odd, even) } else { (even, odd) }
120	}
121	
122	pub fn carry_fuse(left: &str, right: &str) -> Result<CarryFuseReport, String> {
123	    let left = trim_high_empty(left);
124	    let right = trim_high_empty(right);
125	    let a: Vec<u8> = left.chars().map(bit_from_mark).collect::<Result<_, _>>()?;
126	    let b: Vec<u8> = right.chars().map(bit_from_mark).collect::<Result<_, _>>()?;
127	    if a.is_empty() || b.is_empty() {
128	        return Err("carry_fuse needs two non-empty lanes".to_string());
129	    }
130	
131	    let mut carry: u64 = 0;
132	    let mut payload = String::new();
133	    let mut columns = Vec::new();
134	    let max_k = a.len() + b.len() - 2;
135	
136	    for k in 0..=max_k {
137	        let carry_in = carry;
138	        let mut contributions: u64 = 0;
139	        let lo = if k >= b.len() { k - (b.len() - 1) } else { 0 };
140	        let hi = std::cmp::min(a.len() - 1, k);
141	        for i in lo..=hi {
142	            let j = k - i;
143	            contributions += (a[i] as u64) * (b[j] as u64);
144	        }
145	        let total = contributions + carry;
146	        let output_mark = mark_from_bit((total & 1) as u8)?;
147	        let carry_out = total >> 1;
148	        payload.push(output_mark);
149	        columns.push(CarryColumn { k, contributions, carry_in, output_mark, carry_out });
150	        carry = carry_out;
151	    }
152	
153	    let mut k = max_k + 1;
154	    while carry > 0 {
155	        let carry_in = carry;
156	        let output_mark = mark_from_bit((carry & 1) as u8)?;
157	        let carry_out = carry >> 1;
158	        payload.push(output_mark);
159	        columns.push(CarryColumn { k, contributions: 0, carry_in, output_mark, carry_out });
160	        carry = carry_out;
161	        k += 1;
162	    }
163	
164	    Ok(CarryFuseReport { left, right, payload: trim_high_empty(&payload), columns })
165	}
166	
167	pub fn verify_carry_fuse(left: &str, right: &str, payload: &str) -> Result<bool, String> {
168	    Ok(carry_fuse(left, right)?.payload == trim_high_empty(payload))
169	}
170	
171	/// Decimal ingress/audit surface to native mark stream.  This is long division
172	/// by 2 over decimal characters so it has no machine-word size ceiling.
173	pub fn decimal_surface_to_marks(input: &str) -> Result<String, String> {
174	    let mut s = input.trim().to_string();
175	    if s.is_empty() || !s.chars().all(|c| c.is_ascii_digit()) {
176	        return Err(format!("not a decimal surface: {input}"));
177	    }
178	    while s.len() > 1 && s.starts_with('0') { s.remove(0); }
179	    if s == "0" { return Ok(EVALT.to_string()); }
180	
181	    let mut marks = String::new();
182	    while s != "0" {
183	        let mut next = String::new();
184	        let mut rem: u32 = 0;
185	        for ch in s.chars() {
186	            let d = ch.to_digit(10).unwrap();
187	            let x = rem * 10 + d;
188	            let q = x / 2;
189	            rem = x % 2;
190	            if q != 0 || !next.is_empty() { next.push(char::from_digit(q, 10).unwrap()); }
191	        }
192	        marks.push(if rem == 0 { EVALT } else { EVALF });
193	        s = if next.is_empty() { "0".to_string() } else { next };
194	    }
195	    Ok(marks)
196	}
197	
198	/// Shadow conversion from mark stream back to decimal text.  Audit only.
199	pub fn marks_to_decimal_surface(marks: &str) -> Result<String, String> {
200	    let mut digits: Vec<u8> = vec![0];
201	    for mark in marks.chars().rev() {
202	        let bit = bit_from_mark(mark)?;
203	        let mut carry = bit as u16;
204	        for d in digits.iter_mut().rev() {
205	            let x = (*d as u16) * 2 + carry;
206	            *d = (x % 10) as u8;
207	            carry = x / 10;
208	        }
209	        while carry > 0 {
210	            digits.insert(0, (carry % 10) as u8);
211	            carry /= 10;
212	        }
213	    }
214	    Ok(digits.into_iter().map(|d| char::from(b'0' + d)).collect())
215	}
216	
217	pub fn closure_report_from_decimals(a: &str, b: &str) -> Result<String, String> {
218	    let am = decimal_surface_to_marks(a)?;
219	    let bm = decimal_surface_to_marks(b)?;
220	    let cf = carry_fuse(&am, &bm)?;
221	    let shadow = marks_to_decimal_surface(&cf.payload)?;
222	    let word = word_from_marks(&cf.payload)?;
223	
224	    let mut out = String::new();
225	    out.push_str("native_numeral carry/fuse closure\n");
226	    out.push_str(&format!("A_marks: {}\n", am));
227	    out.push_str(&format!("B_marks: {}\n", bm));
228	    out.push_str(&format!("payload_marks: {}\n", cf.payload));
229	    out.push_str(&format!("payload_shadow: {}\n", shadow));
230	    out.push_str(&format!("payload_word: {}\n", word));
231	    out.push_str("columns: k contributions carry_in mark carry_out\n");
232	    for c in cf.columns {
233	        out.push_str(&format!("{} {} {} {} {}\n", c.k, c.contributions, c.carry_in, c.output_mark, c.carry_out));
234	    }
