//! Native numeral carry/fuse closure
//!
//! Grammar object:
//!     D(N) = ⊢ (≻⋈∈s₀∋)(≻⋈∈s₁∋)...(≻⋈∈sₖ∋) ⊙⊡⊣
//! where sᵢ ∈ {⊤, ⊥}.
//!
//! This module does not construct factors by arithmetic division.  It exposes
//! the grammar steps needed by `native_numeral factor`:
//!   1. parse/extract the payload mark stream,
//!   2. expose raw unbraid lanes,
//!   3. close candidate lanes through carry/fuse,
//!   4. accept only if the fused payload equals the target payload.

const VINIT: char = '⊢';
const TANCH: char = '⊣';
const AFWD: char = '≻';
const CLINK: char = '⋈';
const FSPLIT: char = '∈';
const FFUSE: char = '∋';
const EVALT: char = '⊤'; // empty / zero mark in the native payload
const EVALF: char = '⊥'; // occupied / one mark in the native payload
const IMSCRIB: char = '⊙';
const IFIX: char = '⊡';

#[derive(Clone, Debug)]
pub struct CarryColumn {
    pub k: usize,
    pub contributions: u64,
    pub carry_in: u64,
    pub output_mark: char,
    pub carry_out: u64,
}

#[derive(Clone, Debug)]
pub struct CarryFuseReport {
    pub left: String,
    pub right: String,
    pub payload: String,
    pub columns: Vec<CarryColumn>,
}

fn bit_from_mark(c: char) -> Result<u8, String> {
    match c {
        EVALT => Ok(0),
        EVALF => Ok(1),
        _ => Err(format!("bad native numeral mark: {c}")),
    }
}

fn mark_from_bit(b: u8) -> Result<char, String> {
    match b {
        0 => Ok(EVALT),
        1 => Ok(EVALF),
        _ => Err(format!("bad bit: {b}")),
    }
}

pub fn trim_high_empty(s: &str) -> String {
    let mut v: Vec<char> = s.chars().collect();
    while v.len() > 1 && v.last() == Some(&EVALT) {
        v.pop();
    }
    if v.is_empty() { v.push(EVALT); }
    v.into_iter().collect()
}

pub fn word_from_marks(marks: &str) -> Result<String, String> {
    let mut out = String::new();
    out.push(VINIT);
    for mark in marks.chars() {
        bit_from_mark(mark)?;
        out.push(AFWD);
        out.push(CLINK);
        out.push(FSPLIT);
        out.push(mark);
        out.push(FFUSE);
    }
    out.push(IMSCRIB);
    out.push(IFIX);
    out.push(TANCH);
    Ok(out)
}

pub fn extract_mark_stream(word: &str) -> Result<String, String> {
    let chars: Vec<char> = word.chars().filter(|c| !c.is_whitespace()).collect();
    if chars.first() != Some(&VINIT) {
        return Err("native numeral word must start with ⊢".to_string());
    }
    if chars.len() < 4 || chars[chars.len() - 3..] != [IMSCRIB, IFIX, TANCH] {
        return Err("native numeral word must close with ⊙⊡⊣".to_string());
    }
    let mut marks = String::new();
    let mut i = 1usize;
    let stop = chars.len() - 3;
    while i < stop {
        if i + 4 >= stop + 1 {
            return Err(format!("truncated cell at glyph offset {i}"));
        }
        if chars[i] != AFWD || chars[i + 1] != CLINK || chars[i + 2] != FSPLIT {
            return Err(format!("bad cell prefix at glyph offset {i}"));
        }
        let mark = chars[i + 3];
        bit_from_mark(mark)?;
        if chars[i + 4] != FFUSE {
            return Err(format!("bad cell suffix after glyph offset {}", i + 3));
        }
        marks.push(mark);
        i += 5;
    }
    Ok(marks)
}

pub fn raw_unbraid(marks: &str, a_first: bool) -> (String, String) {
    let mut odd = String::new();
    let mut even = String::new();
    for (i, ch) in marks.chars().enumerate() {
        if i % 2 == 0 { odd.push(ch); } else { even.push(ch); }
    }
    if a_first { (odd, even) } else { (even, odd) }
}

pub fn carry_fuse(left: &str, right: &str) -> Result<CarryFuseReport, String> {
    let left = trim_high_empty(left);
    let right = trim_high_empty(right);
    let a: Vec<u8> = left.chars().map(bit_from_mark).collect::<Result<_, _>>()?;
    let b: Vec<u8> = right.chars().map(bit_from_mark).collect::<Result<_, _>>()?;
    if a.is_empty() || b.is_empty() {
        return Err("carry_fuse needs two non-empty lanes".to_string());
    }

    let mut carry: u64 = 0;
    let mut payload = String::new();
    let mut columns = Vec::new();
    let max_k = a.len() + b.len() - 2;

    for k in 0..=max_k {
        let carry_in = carry;
        let mut contributions: u64 = 0;
        let lo = if k >= b.len() { k - (b.len() - 1) } else { 0 };
        let hi = std::cmp::min(a.len() - 1, k);
        for i in lo..=hi {
            let j = k - i;
            contributions += (a[i] as u64) * (b[j] as u64);
        }
        let total = contributions + carry;
        let output_mark = mark_from_bit((total & 1) as u8)?;
        let carry_out = total >> 1;
        payload.push(output_mark);
        columns.push(CarryColumn { k, contributions, carry_in, output_mark, carry_out });
        carry = carry_out;
    }

    let mut k = max_k + 1;
    while carry > 0 {
        let carry_in = carry;
        let output_mark = mark_from_bit((carry & 1) as u8)?;
        let carry_out = carry >> 1;
        payload.push(output_mark);
        columns.push(CarryColumn { k, contributions: 0, carry_in, output_mark, carry_out });
        carry = carry_out;
        k += 1;
    }

    Ok(CarryFuseReport { left, right, payload: trim_high_empty(&payload), columns })
}

pub fn verify_carry_fuse(left: &str, right: &str, payload: &str) -> Result<bool, String> {
    Ok(carry_fuse(left, right)?.payload == trim_high_empty(payload))
}

/// Decimal ingress/audit surface to native mark stream.  This is long division
/// by 2 over decimal characters so it has no machine-word size ceiling.
pub fn decimal_surface_to_marks(input: &str) -> Result<String, String> {
    let mut s = input.trim().to_string();
    if s.is_empty() || !s.chars().all(|c| c.is_ascii_digit()) {
        return Err(format!("not a decimal surface: {input}"));
    }
    while s.len() > 1 && s.starts_with('0') { s.remove(0); }
    if s == "0" { return Ok(EVALT.to_string()); }

    let mut marks = String::new();
    while s != "0" {
        let mut next = String::new();
        let mut rem: u32 = 0;
        for ch in s.chars() {
            let d = ch.to_digit(10).unwrap();
            let x = rem * 10 + d;
            let q = x / 2;
            rem = x % 2;
            if q != 0 || !next.is_empty() { next.push(char::from_digit(q, 10).unwrap()); }
        }
        marks.push(if rem == 0 { EVALT } else { EVALF });
        s = if next.is_empty() { "0".to_string() } else { next };
    }
    Ok(marks)
}

/// Shadow conversion from mark stream back to decimal text.  Audit only.
pub fn marks_to_decimal_surface(marks: &str) -> Result<String, String> {
    let mut digits: Vec<u8> = vec![0];
    for mark in marks.chars().rev() {
        let bit = bit_from_mark(mark)?;
        let mut carry = bit as u16;
        for d in digits.iter_mut().rev() {
            let x = (*d as u16) * 2 + carry;
            *d = (x % 10) as u8;
            carry = x / 10;
        }
        while carry > 0 {
            digits.insert(0, (carry % 10) as u8);
            carry /= 10;
        }
    }
    Ok(digits.into_iter().map(|d| char::from(b'0' + d)).collect())
}

pub fn closure_report_from_decimals(a: &str, b: &str) -> Result<String, String> {
    let am = decimal_surface_to_marks(a)?;
    let bm = decimal_surface_to_marks(b)?;
    let cf = carry_fuse(&am, &bm)?;
    let shadow = marks_to_decimal_surface(&cf.payload)?;
    let word = word_from_marks(&cf.payload)?;

    let mut out = String::new();
    out.push_str("native_numeral carry/fuse closure\n");
    out.push_str(&format!("A_marks: {}\n", am));
    out.push_str(&format!("B_marks: {}\n", bm));
    out.push_str(&format!("payload_marks: {}\n", cf.payload));
    out.push_str(&format!("payload_shadow: {}\n", shadow));
    out.push_str(&format!("payload_word: {}\n", word));
    out.push_str("columns: k contributions carry_in mark carry_out\n");
    for c in cf.columns {
        out.push_str(&format!("{} {} {} {} {}\n", c.k, c.contributions, c.carry_in, c.output_mark, c.carry_out));
    }
    Ok(out)
}

