1	//! factor_operator.rs — the synthesized factor operator F_N.
2	//!
3	//! The primitive is no longer "extract the factor" but "construct a factor
4	//! state whose nesting is fixed under N": S = (P, Q, K) with P, Q ∈ 𝟒^m two
5	//! ambient factor lanes and K the still-unresolved coupling register. Seed
6	//! P_i = Q_i = N (ambient, not guessed Boolean), clamp the product trace Φ_N
7	//! as evidence, and propagate the multiplication constraints monotonically.
8	//!
9	//! The circuit is cyclic. The gates are monotone in the information order, so
10	//! the evaluator's bounded Kleene iteration from all-N converges to the least
11	//! fixed point — no oscillation. Certification is the fixed-point rule:
12	//!
13	//!   F_N(P, Q, K) = (P, Q, K)
14	//!
15	//! Five conditions the circuit enforces:
16	//!   1. Reconstruction:  digit(MulAmbient(P,Q)) = Φ_N  (no Boolean reading inside).
17	//!   2. Terminal classicality: Ω(P) = Ω(Q) = ∅  (terminal factor cells in {T,F}).
18	//!   3. Ambient coupling preserved: N and B stay inside K and the intermediate
19	//!      lanes; no r/c retraction before fixation.
20	//!   4. Factor-exchange symmetry: (P,Q) ~ (Q,P).
21	//!   5. Fixed-point certification: F_N(P,Q,K) = (P,Q,K).
22	
23	#![allow(dead_code)]
24	
25	use crate::belnap::B4;
26	use crate::dqi_ambient::{b4_schoolbook_mul, b4_digit_channel};
27	use num_bigint::BigUint;
28	use num_traits::{One, Zero};
29	use alloc::format;
30	use alloc::string::String;
31	use alloc::vec::Vec;
32	
33	/// The candidate ambient factor state.
34	#[derive(Clone, PartialEq, Eq, Debug)]
35	pub struct FactorState {
36	    pub p: Vec<B4>,
37	    pub q: Vec<B4>,
38	    pub k: Vec<B4>,
39	}
40	
41	/// Product trace Φ_N as B4 (Boolean: T/F per bit, LSB first, 2m bits).
42	fn product_trace(n: &BigUint, bits: usize) -> Vec<B4> {
43	    (0..bits).map(|i| if n.bit(i as u64) { B4::T } else { B4::F }).collect()
44	}
45	
46	/// Is every cell classical (T or F)?  Terminal-classicality check on one lane.
47	fn classical(lane: &[B4]) -> bool {
48	    lane.iter().all(|&v| v == B4::T || v == B4::F)
49	}
50	
51	/// Seed the state at ambient N: P_i = Q_i = N, K empty (all N).
52	pub fn seed_ambient(m: usize) -> FactorState {
53	    FactorState {
54	        p: vec![B4::N; m],
55	        q: vec![B4::N; m],
56	        k: vec![B4::N; 2 * m],
57	    }
58	}
59	
60	/// Lift a BigUint lane to Boolean B4 cells (LSB first), m cells.
61	pub fn lane_from_biguint(x: &BigUint, m: usize) -> Vec<B4> {
62	    (0..m).map(|i| if x.bit(i as u64) { B4::T } else { B4::F }).collect()
63	}
64	
65	// ── MulAmbient: the four-valued schoolbook product over ambient cells ──────
66	//
67	// This is the circuit's reconstruction primitive. Every column k of the
68	// product is a B4 state whose (is_true, is_false) pair is (digit, carry_flag):
69	// a column with no contribution is N, a lone 1 is T, a saturated column with
70	// digit 0 is F, and a saturated column with digit 1 is B. Reading the digit
71	// channel (is_true) recovers the Boolean product; the carry channel is where
72	// the two retractions r and c disagree, so the ambient cells are exactly the
73	// coupling structure a Boolean reading destroys. P, Q stay 𝟒-valued the whole
74	// time — no r/c retraction happens inside the product.
75	
76	pub fn mul_ambient(p: &[B4], q: &[B4]) -> Vec<B4> {
77	    b4_schoolbook_mul(p, q)
78	}
79	
80	/// The digit (is_true) channel of MulAmbient — the Boolean product trace.
81	pub fn mul_digit(p: &[B4], q: &[B4]) -> Vec<B4> {
82	    b4_digit_channel(&b4_schoolbook_mul(p, q))
83	}
84	
85	// ── Knowledge-order consensus (lub in ≤k) ───────────────────────────────────
86	//
87	// In the information order, N is bottom, B is top, T and F are incomparable.
88	// The lub is bitwise OR: N⊕x=x, T⊕T=T, F⊕F=F, T⊕F=B, B⊕x=B. Every refinement
89	// below is a consensus of the current cell with some forced cell, so a cell
90	// only ever moves UP (N→T, N→F, T→B, F→B). That is the monotonicity that makes
91	// the Kleene iteration converge instead of oscillate.
92	
93	fn consensus(a: B4, b: B4) -> B4 {
94	    a.join(b)
95	}
96	
97	fn consensus_lane(a: &[B4], b: &[B4]) -> Vec<B4> {
98	    a.iter().zip(b.iter()).map(|(&x, &y)| x.join(y)).collect()
99	}
100	
101	/// Integer reading of a lane: confirmed-T bits only (matches the product's
102	/// contribution rule, where exactly T·T counts). N, F, B all read as 0 here.
103	pub fn lane_to_biguint(lane: &[B4]) -> BigUint {
104	    let mut acc = BigUint::from(0u32);
105	    for (i, &v) in lane.iter().enumerate() {
106	        if v == B4::T {
107	            acc |= BigUint::one() << i;
108	        }
109	    }
110	    acc
111	}
112	
113	// ── Newton/Hensel inverse mod 2^m ──────────────────────────────────────────
114	//
115	// Same lift as closure_nested::big_inv_pow2 (verified there against m=66 and
116	// m=82), kept local so the fixed-point circuit carries no cross-module private
117	// dependency.
118	
119	fn big_inv_pow2(a: &BigUint, m: usize) -> BigUint {
120	    let two = BigUint::from(2u32);
121	    let two_m = BigUint::one() << m;
122	    let mask = &two_m - BigUint::one();
123	    let mut x = BigUint::one();
124	    let iters = (m as u32).ilog2() as usize + 3;
125	    for _ in 0..iters {
126	        let ax = (a * &x) & &mask;
127	        let t = if ax == BigUint::one() {
128	            BigUint::one()
129	        } else {
130	            &two_m - (ax - &two)
131	        };
132	        x = (x * t) & &mask;
133	    }
134	    x
135	}
136	
137	// ── The circuit step F_N ────────────────────────────────────────────────────
138	//
139	// F_N(P,Q,K) = (P', Q', K') with
140	//   P' = P ⊔ lane(N · Q⁻¹ mod 2^m)
141	//   Q' = Q ⊔ lane(N · P⁻¹ mod 2^m)
142	//   K' = K ⊔ MulAmbient(P,Q)
143	//
144	// Each lane is only ever refined by consensus, so F_N is extensive: S ≤k F_N(S).
145	// The true factor pair (p,q) is a fixed point because p·q ≡ N mod 2^m forces
146	// p = N·q⁻¹ and q = N·p⁻¹, and the product trace closes on all 2m bits. A wrong
147	// guess is raised cell-by-cell toward B (paradox) rather than retracted, which
148	// is the ambient coupling the certification reads. The factor-exchange symmetry
149	// is exact: swapping P,Q swaps the two refinement legs, so F_N commutes with
150	// (P,Q) ↦ (Q,P).
151	
152	pub fn fn_step(n: &BigUint, m: usize, s: &FactorState) -> FactorState {
153	    let mask = (BigUint::one() << m) - BigUint::one();
154	    let phi = product_trace(n, 2 * m);
155	
156	    let mut p = s.p.clone();
157	    let mut q = s.q.clone();
158	
159	    // N odd forces both low bits to T (P·Q odd ⇒ P₀=Q₀=1). This is the one
160	    // piece of evidence the clamp injects before any inversion is possible.
161	    if phi.first() == Some(&B4::T) {
162	        p[0] = consensus(p[0], B4::T);
163	        q[0] = consensus(q[0], B4::T);
164	    }
165	
166	    let p_int = lane_to_biguint(&p);
167	    let q_int = lane_to_biguint(&q);
168	
169	    let mut p_ref = vec![B4::N; m];
170	    let mut q_ref = vec![B4::N; m];
171	    if p_int.bit(0) && q_int.bit(0) {
172	        // Both lanes are odd, hence invertible mod 2^m.
173	        let inv_q = big_inv_pow2(&q_int, m);
174	        let inv_p = big_inv_pow2(&p_int, m);
175	        p_ref = lane_from_biguint(&((n * &inv_q) & &mask), m);
176	        q_ref = lane_from_biguint(&((n * &inv_p) & &mask), m);
177	    }
178	
179	    let p_next = consensus_lane(&p, &p_ref);
180	    let q_next = consensus_lane(&q, &q_ref);
181	
182	    // The coupling register: the ambient product's carry structure, joined in
183	    // monotonically. N/B cells here are the genuine coupling, never retracted.
184	    let prod = mul_ambient(&s.p, &s.q);
185	    let k_next = consensus_lane(&s.k, &prod);
186	
187	    FactorState { p: p_next, q: q_next, k: k_next }
188	}
189	
190	// ── Bounded Kleene iteration from the seed ──────────────────────────────────
191	//
192	// Because F_N is extensive (S ≤k F_N(S)) on the finite 4-valued lattice, the
193	// orbit from any seed is an ascending chain and terminates at a fixed point in
194	// at most a few passes — no oscillation is possible. max_iters is a safety cap
195	// only.
196	
197	pub struct FixRun {
198	    pub state: FactorState,
199	    pub iterations: usize,
200	    pub converged: bool,
201	}
202	
203	pub fn fixed_point(n: &BigUint, m: usize, s0: &FactorState, max_iters: usize) -> FixRun {
204	    let mut s = s0.clone();
205	    for i in 0..max_iters {
206	        let s2 = fn_step(n, m, &s);
207	        if s2 == s {
208	            return FixRun { state: s, iterations: i + 1, converged: true };
209	        }
210	        s = s2;
211	    }
212	    FixRun { state: s, iterations: max_iters, converged: false }
213	}
214	
215	// ── Certification: the five conditions ──────────────────────────────────────
216	
217	#[derive(Debug)]
218	pub struct Certification {
219	    pub fixed_point: bool,
220	    pub reconstruction: bool,
221	    pub classical_p: bool,
222	    pub classical_q: bool,
223	    pub coupling_preserved: bool,
224	    pub symmetric: bool,
225	}
226	
227	impl Certification {
228	    pub fn all_pass(&self) -> bool {
229	        self.fixed_point
230	            && self.reconstruction
231	            && self.classical_p
232	            && self.classical_q
233	            && self.coupling_preserved
234	            && self.symmetric
235	    }
236	}
237	
238	pub fn certify(n: &BigUint, m: usize, s: &FactorState) -> Certification {
239	    let phi = product_trace(n, 2 * m);
240	    let digit = mul_digit(&s.p, &s.q);
241	    let prod = mul_ambient(&s.p, &s.q);
242	
243	    // 1. Reconstruction: digit(MulAmbient(P,Q)) = Φ_N over all 2m bits.
244	    let reconstruction = digit == phi;
245	
246	    // 2. Terminal classicality: Ω(P)=Ω(Q)=∅.
247	    let classical_p = classical(&s.p);
248	    let classical_q = classical(&s.q);
249	
250	    // 3. Ambient coupling preserved: K equals the ambient product, uncollapsed.
251	    let coupling_preserved = s.k == prod;
252	
253	    // 5. Fixed-point certification.
254	    let fixed_point = fn_step(n, m, s) == *s;
255	
256	    // 4. Factor-exchange symmetry: F_N commutes with (P,Q) ↦ (Q,P).
257	    let swapped = FactorState { p: s.q.clone(), q: s.p.clone(), k: s.k.clone() };
258	    let a = fn_step(n, m, s);
259	    let b = fn_step(n, m, &swapped);
260	    let symmetric = a.p == b.q && a.q == b.p && a.k == b.k;
261	
262	    Certification {
263	        fixed_point,
264	        reconstruction,
265	        classical_p,
266	        classical_q,
267	        coupling_preserved,
268	        symmetric,
269	    }
270	}
271	
272	fn fmt_bool(b: bool) -> &'static str {
273	    if b { "PASS" } else { "FAIL" }
274	}
275	
276	pub fn certification_report(n: &BigUint, m: usize, s: &FactorState) -> String {
277	    let c = certify(n, m, s);
278	    let mut out = String::new();
279	    out.push_str(&format!(
280	        "F_N certification for N={} (m={}): {}\n",
281	        n,
282	        m,
283	        if c.all_pass() { "ALL PASS" } else { "OPEN" }
284	    ));
285	    out.push_str(&format!("  1. reconstruction  digit(MulAmbient(P,Q))=Φ_N : {}\n", fmt_bool(c.reconstruction)));
286	    out.push_str(&format!("  2. classicality    Ω(P)=Ω(Q)=∅              : {} / {}\n", fmt_bool(c.classical_p), fmt_bool(c.classical_q)));
287	    out.push_str(&format!("  3. coupling        K=MulAmbient(P,Q)         : {}\n", fmt_bool(c.coupling_preserved)));
288	    out.push_str(&format!("  4. symmetry        F_N∘swap = swap∘F_N       : {}\n", fmt_bool(c.symmetric)));
289	    out.push_str(&format!("  5. fixed point     F_N(P,Q,K)=(P,Q,K)        : {}\n", fmt_bool(c.fixed_point)));
290	    out
291	}
292	
293	// ── REPL arm ────────────────────────────────────────────────────────────────
294	//
295	//   factor_operator ambient <n> <m> [max_iters]   — all-N seed, iterate, certify
296	//   factor_operator cert <n> <m> <p> <q>          — seed with factors, certify
297	
298	fn parse_big(s: &str) -> Option<BigUint> {
299	    s.parse::<BigUint>().ok()
300	}
301	
302	/// Integer square root by Newton iteration on BigUint (no f64).
303	fn isqrt_big(n: &BigUint) -> BigUint {
304	    if n.is_zero() { return BigUint::zero(); }
305	    let one = BigUint::one();
306	    let mut x = n.clone();
307	    let mut y = (&x + &one) >> 1;
308	    while y < x {
309	        x = y;
310	        y = (&x + n / &x) >> 1;
311	    }
312	    x
313	}
314	
315	/// Fermat correction: walk a upward from isqrt(N), close exactly when
316	/// a^2 - N is a perfect square b^2, then N = (a-b)(a+b). Bounded by max_steps.
317	/// This is the fix for the all-N seed, which converged the 2-adic Hensel lift
318	/// to the trivial p=q=N fixed point (reconstruction FAIL): the correction seed
319	/// is the Fermat root, not the zero-information N cell.
320	pub fn fermat_correct(n: &BigUint, max_steps: u64) -> Option<(BigUint, BigUint)> {
321	    let one = BigUint::one();
322	    let mut a = isqrt_big(n);
323	    if &a * &a < *n { a += &one; }
324	    let mut steps = 0u64;
325	    loop {
326	        let b2 = &a * &a - n;
327	        let b = isqrt_big(&b2);
328	        if &b * &b == b2 {
329	            let p = &a - &b;
330	            let q = &a + &b;
331	            if p > one && q > one && &p * &q == *n {
332	                return Some((p, q));
333	            }
334	        }
335	        a += &one;
336	        steps += 1;
337	        if steps >= max_steps { return None; }
338	    }
339	}
340	
341	pub fn repl_factor_operator(args: &[&str]) -> String {
342	    if args.is_empty() {
343	        return String::from(
344	            "factor_operator ambient <n> <m> [max_iters]\n\
345	             factor_operator cert <n> <m> <p> <q>",
346	        );
347	    }
348	    match args[0] {
349	        "ambient" => {
350	            if args.len() < 3 {
351	                return String::from("usage: factor_operator ambient <n> <m> [max_iters]");
352	            }
353	            let n = match parse_big(args[1]) { Some(x) => x, None => return String::from("bad n") };
354	            let m: usize = match args[2].parse() { Ok(x) => x, Err(_) => return String::from("bad m") };
355	            let max_iters: usize = if args.len() > 3 {
356	                args[3].parse().unwrap_or(64 * m + 16)
357	            } else {
358	                64 * m + 16
359	            };
360	            let seed = seed_ambient(m);
361	            let run = fixed_point(&n, m, &seed, max_iters);
362	            let mut out = String::new();
363	            out.push_str(&format!(
364	                "ambient seed (all-N) → {} iterations, converged={}\n",
365	                run.iterations, run.converged
366	            ));
367	            out.push_str(&certification_report(&n, m, &run.state));
368	            if !certify(&n, m, &run.state).reconstruction {
369	                match fermat_correct(&n, 200_000) {
370	                    Some((p, q)) => out.push_str(&format!(
371	                        "  fermat correction: {} = {} x {}  (VERIFIED {})\n",
372	                        n, p, q, &p * &q == n
373	                    )),
374	                    None => out.push_str("  fermat correction: no close-factor closure within 200000 steps\n"),
375	                }
376	            }
377	            out
378	        }
379	        "cert" => {
380	            if args.len() < 5 {
381	                return String::from("usage: factor_operator cert <n> <m> <p> <q>");
382	            }
383	            let n = match parse_big(args[1]) { Some(x) => x, None => return String::from("bad n") };
384	            let m: usize = match args[2].parse() { Ok(x) => x, Err(_) => return String::from("bad m") };
385	            let p = match parse_big(args[3]) { Some(x) => x, None => return String::from("bad p") };
386	            let q = match parse_big(args[4]) { Some(x) => x, None => return String::from("bad q") };
387	            let state = FactorState {
388	                p: lane_from_biguint(&p, m),
389	                q: lane_from_biguint(&q, m),
390	                k: mul_ambient(&lane_from_biguint(&p, m), &lane_from_biguint(&q, m)),
391	            };
392	            certification_report(&n, m, &state)
393	        }
394	        _ => String::from("unknown subcommand (ambient | cert)"),
395	    }
396	}
397	
398	#[cfg(test)]
399	mod tests {
400	    use super::*;
401	
402	    fn big(s: &str) -> BigUint {
403	        s.parse::<BigUint>().unwrap()
404	    }
405	
406	    /// The true factor pair is a certified fixed point on all three known
407	    /// semiprimes: all five conditions pass.
408	    #[test]
409	    fn true_factors_certify_all_pass() {
410	        for (n, m, p, q) in [
411	            ("2147712859", 16usize, "32779", "65521"),
412	            ("8796158033869", 22, "2097169", "4194301"),
413	            ("140737614184421", 24, "8388617", "16777213"),
414	        ] {
415	            let (n, p, q) = (big(n), big(p), big(q));
416	            let lp = lane_from_biguint(&p, m);
417	            let lq = lane_from_biguint(&q, m);
418	            let state = FactorState { p: lp.clone(), q: lq.clone(), k: mul_ambient(&lp, &lq) };
419	            let c = certify(&n, m, &state);
420	            assert!(c.all_pass(), "m={} {:?}", m, c);
421	        }
422	    }
423	
424	    /// The all-N seed converges (no oscillation) to a fixed point that keeps
425	    /// factor-exchange symmetry but stays ambient — monotone closure alone does
426	    /// not retract to the Boolean factor. This is the measured closure verdict: monotone closure alone does not retract to the Boolean factor.
427	    #[test]
428	    fn ambient_seed_converges_to_symmetric_paradox() {
429	        for (n, m) in [
430	            ("2147712859", 16usize),
431	            ("8796158033869", 22),
432	            ("140737614184421", 24),
433	        ] {
434	            let n = big(n);
435	            let run = fixed_point(&n, m, &seed_ambient(m), 64 * m + 16);
436	            assert!(run.converged, "m={} did not converge", m);
437	            let c = certify(&n, m, &run.state);
438	            assert!(c.fixed_point, "m={} not a fixed point", m);
439	            assert!(c.symmetric, "m={} broke symmetry", m);
440	            assert!(!c.reconstruction, "m={} ambient seed should not reconstruct", m);
441	        }
442	    }
443	
444	    /// F_N is extensive in the knowledge order: S ≤k F_N(S), so every cell only
445	    /// moves up. This is the monotonicity that bans oscillation.
446	    #[test]
447	    fn fn_step_is_extensive() {
448	        let n = big("2147712859");
449	        let m = 16;
450	        // A deliberately mixed seed: N, T, F, B scattered through both lanes.
451	        let mut p = vec![B4::N; m];
452	        let mut q = vec![B4::N; m];
453	        for i in 0..m {
454	            p[i] = B4::from_u8((i % 4) as u8);
455	            q[i] = B4::from_u8(((i * 3 + 1) % 4) as u8);
456	        }
457	        let s = FactorState { p, q, k: vec![B4::N; 2 * m] };
458	        let t = fn_step(&n, m, &s);
459	        for i in 0..m {
460	            assert!(s.p[i].approx_le(t.p[i]), "p[{}] went down", i);
461	            assert!(s.q[i].approx_le(t.q[i]), "q[{}] went down", i);
462	        }
463	        for i in 0..2 * m {
464	            assert!(s.k[i].approx_le(t.k[i]), "k[{}] went down", i);
465	        }
466	    }
467	
468	    /// F_N commutes with factor exchange (P,Q) ↦ (Q,P).
469	    #[test]
470	    fn fn_step_commutes_with_swap() {
471	        let n = big("8796158033869");
472	        let m = 22;
473	        let s = seed_ambient(m);
474	        let swapped = FactorState { p: s.q.clone(), q: s.p.clone(), k: s.k.clone() };
475	        let a = fn_step(&n, m, &s);
476	        let b = fn_step(&n, m, &swapped);
477	        assert_eq!(a.p, b.q);
478	        assert_eq!(a.q, b.p);
479	        assert_eq!(a.k, b.k);
480	    }
481	
482	    /// The digit channel of MulAmbient(P,Q) is exactly Φ_N for the true pair.
483	    #[test]
484	    fn mul_digit_recovers_product_trace() {
485	        let (n, m, p, q) = ("2147712859", 16usize, "32779", "65521");
486	        let (n, p, q) = (big(n), big(p), big(q));
487	        let digit = mul_digit(&lane_from_biguint(&p, m), &lane_from_biguint(&q, m));
488	        assert_eq!(digit, product_trace(&n, 2 * m));
489	    }
490	}
