14	/// Low arm state: low k bits of each factor + low carry residual.
15	#[derive(Clone, Debug, PartialEq, Eq)]
16	pub struct LowState {
17	    pub p_low: u64,
18	    pub q_low: u64,
19	    pub k: u32,
20	    /// (p_low*q_low - N) mod 2^k == 0 iff consistent
21	    pub consistent_mod: bool,
22	}
23	
24	/// High arm state: top l bits of each factor + prefix-interval verdict.
25	#[derive(Clone, Debug, PartialEq, Eq)]
26	pub struct HighState {
27	    pub p_high: u64,
28	    pub q_high: u64,
29	    pub l: u32,
30	    pub consistent_prefix: bool,
31	}
