33	/// Bridge verdict for one low/high pair.
34	#[derive(Clone, Debug, PartialEq, Eq)]
35	pub enum Bridge {
36	    Consistent,
37	    LowConflict,
38	    HighConflict,
39	    SpliceConflict,
40	}
41	
42	/// Low condition: exists full-width pair extending these low bits with
43	/// P*Q == N (mod 2^k). Checked by exhaustive extension (bounded m, solution-blind).
44	pub fn low_consistent(n: u64, m: u32, p_low: u64, q_low: u64, k: u32) -> bool {
45	    if k == 0 {
46	        return true;
47	    }
48	    let mask: u64 = if k >= 64 { u64::MAX } else { (1u64 << k) - 1 };
49	    let lo: u64 = 1u64 << (m - 1);
50	    let hi: u64 = (1u64 << m) - 1;
51	    let mut p = lo | 1;
52	    while p <= hi {
53	        if p & mask == p_low & mask {
54	            let mut q = lo | 1;
55	            while q <= hi {
56	                if q & mask == q_low & mask && p.wrapping_mul(q) == n {
57	                    return true;
58	                }
59	                if q == hi {
60	                    break;
61	                }
62	                q += 2;
63	            }
64	        }
65	        if p == hi {
66	            break;
67	        }
68	        p += 2;
69	    }
70	    false
71	}
72	
73	/// High condition: the pair's full product prefix matches N's prefix, i.e.
74	/// floor(PQ/2^{2m-2l}) == floor(N/2^{2m-2l}); at l>=m this is PQ==N.
75	pub fn high_consistent(n: u64, m: u32, p: u64, q: u64, l: u32) -> bool {
76	    if l == 0 {
77	        return true;
78	    }
79	    if l >= m {
80	        return p.wrapping_mul(q) == n;
81	    }
82	    let shift = 2 * m - 2 * l;
83	    (p.wrapping_mul(q) >> shift) == (n >> shift)
84	}
85	
86	/// Bridge B(L_k,H_l;N): both sides must extend to a TRUE factor pair
87	/// (p*,q*) with p*q==N that agrees with both partial states. Incompatible
88	/// assignments yield the inconsistent state and kill that branch.
89	pub fn bridge(
90	    n: u64,
91	    m: u32,
92	    low: &LowState,
93	    high: &HighState,
94	    p_star: u64,
95	    q_star: u64,
96	) -> Bridge {
97	    let mask_l: u64 = if low.k >= 64 || low.k == 0 {
98	        0
99	    } else {
100	        (1u64 << low.k) - 1
101	    };
102	    let agree_low =
103	        low.k == 0 || (p_star & mask_l == low.p_low & mask_l && q_star & mask_l == low.q_low & mask_l)
104	            || (p_star & mask_l == low.q_low & mask_l && q_star & mask_l == low.p_low & mask_l);
105	    if !agree_low || !low.consistent_mod {
106	        return Bridge::LowConflict;
107	    }
108	    let agree_high = high.l == 0
109	        || (p_star >> (m - high.l) == high.p_high && q_star >> (m - high.l) == high.q_high)
110	        || (p_star >> (m - high.l) == high.q_high && q_star >> (m - high.l) == high.p_high);
111	    if !agree_high || !high.consistent_prefix {
112	        return Bridge::HighConflict;
113	    }
114	    if p_star.wrapping_mul(q_star) != n {
115	        return Bridge::SpliceConflict;
116	    }
117	    Bridge::Consistent
118	}
119	
120	/// True factor pairs (p,q) at width m with p*q==n (both orders kept).
121	pub fn true_pairs(n: u64, m: u32) -> Vec<(u64, u64)> {
122	    let lo: u64 = 1u64 << (m - 1);
123	    let hi: u64 = (1u64 << m) - 1;
124	    let mut out = Vec::new();
125	    let mut p = lo | 1;
126	    loop {
127	        if n % p == 0 {
128	            let q = n / p;
129	            if q >= lo && q <= hi && q & 1 == 1 {
130	                out.push((p, q));
131	            }
132	        }
133	        if p == hi {
134	            break;
135	        }
136	        p += 2;
137	    }
138	    out
139	}
140	
141	/// Solution-blind low candidates: all odd low-k bit pairs with
142	/// pl*ql == N (mod 2^k). No solution knowledge used.
143	pub fn low_candidates(n: u64, k: u32) -> Vec<(u64, u64)> {
144	    if k == 0 { return alloc::vec![(0, 0)]; }
145	    let modk: u64 = if k >= 64 { 0 } else { 1u64 << k };
146	    let mask = modk.wrapping_sub(1);
147	    let nmask = n & mask;
148	    let mut out = Vec::new();
149	    let mut pl = 1u64;
150	    while pl < modk {
151	        let mut ql = 1u64;
152	        while ql < modk {
153	            if pl.wrapping_mul(ql) & mask == nmask { out.push((pl, ql)); }
154	            if ql + 2 >= modk + 1 { break; }
155	            ql += 2;
156	            if ql >= modk { break; }
157	        }
158	        if pl + 2 >= modk + 1 { break; }
159	        pl += 2;
160	        if pl >= modk { break; }
161	    }
162	    out
163	}
164	
165	/// Solution-blind high candidates: top-l bit pairs whose product interval
166	/// overlaps the N prefix block. No solution knowledge used.
167	pub fn high_candidates(n: u64, m: u32, l: u32) -> Vec<(u64, u64)> {
168	    if l == 0 { return alloc::vec![(0, 0)]; }
169	    if l >= m {
170	        // full width: local check is exact product
171	        let lo: u64 = (1u64 << (m - 1)) | 1;
172	        let hi: u64 = (1u64 << m) - 1;
173	        let mut out = Vec::new();
174	        let mut ph = lo;
175	        while ph <= hi {
176	            let mut qh = lo;
177	            while qh <= hi {
178	                if ph.wrapping_mul(qh) == n { out.push((ph, qh)); }
179	                if qh == hi { break; }
180	                qh += 2;
181	            }
182	            if ph == hi { break; }
183	            ph += 2;
184	        }
185	        return out;
186	    }
187	    let shift = 2 * m - 2 * l;
188	    let npref = n >> shift;
189	    let blk_lo = npref << shift;
190	    let blk_hi = ((npref + 1) << shift).wrapping_sub(1);
191	    let mut out = Vec::new();
192	    let lo_top: u64 = 1u64 << (l - 1);
193	    let hi_top: u64 = (1u64 << l) - 1;
194	    for ph in lo_top..=hi_top {
195	        for qh in lo_top..=hi_top {
196	            let p_lo = ph << (m - l);
197	            let p_hi = ((ph + 1) << (m - l)).wrapping_sub(1);
198	            let q_lo = qh << (m - l);
199	            let q_hi = ((qh + 1) << (m - l)).wrapping_sub(1);
200	            let lo_prod = p_lo.wrapping_mul(q_lo);
201	            let hi_prod = p_hi.wrapping_mul(q_hi);
202	            if !(hi_prod < blk_lo || lo_prod > blk_hi) { out.push((ph, qh)); }
203	        }
204	    }
205	    out
206	}
207	
208	/// Solution-blind bridge: does there exist a completion of the middle bits
209	/// with P*Q == N agreeing with both partial states? Searched by exhaustive
210	/// middle enumeration (bounded m<=30). Returns true iff jointly extendable.
211	pub fn bridge_extendable(n: u64, m: u32, pl: u64, ql: u64, k: u32, ph: u64, qh: u64, l: u32) -> bool {
212	    if k == 0 && l == 0 { return true; }
213	    let lo: u64 = 1u64 << (m - 1);
214	    let hi: u64 = (1u64 << m) - 1;
215	    let mask: u64 = if k == 0 || k >= 64 { 0 } else { (1u64 << k) - 1 };
216	    // iterate over p with matching low+high, then solve for q via middle enumeration
217	    let mut p = lo | 1;
218	    loop {
219	        let lok = k == 0 || (p & mask == pl & mask);
220	        let hik = l == 0 || (p >> (m - l) == ph);
221	        if lok && hik {
222	            // q must match low bits and high bits; enumerate middle
223	            let mut q = lo | 1;
224	            loop {
225	                let qlok = k == 0 || (q & mask == ql & mask);
226	                let qhik = l == 0 || (q >> (m - l) == qh);
227	                if qlok && qhik && p.wrapping_mul(q) == n { return true; }
228	                // also allow swapped lanes
229	                let qlok2 = k == 0 || (q & mask == pl & mask);
230	                let qhik2 = l == 0 || (q >> (m - l) == ph);
231	                let plok2 = k == 0 || (p & mask == ql & mask);
232	                let phik2 = l == 0 || (p >> (m - l) == qh);
233	                if plok2 && phik2 && qlok2 && qhik2 && p.wrapping_mul(q) == n { return true; }
234	                if q == hi { break; }
235	                q += 2;
236	            }
237	        }
238	        // swapped lanes for p
239	        let lok2 = k == 0 || (p & mask == ql & mask);
240	        let hik2 = l == 0 || (p >> (m - l) == qh);
241	        if (lok2 && hik2) && !(lok && hik) {
242	            let mut q = lo | 1;
243	            loop {
244	                let qlok = k == 0 || (q & mask == pl & mask);
245	                let qhik = l == 0 || (q >> (m - l) == ph);
246	                if qlok && qhik && p.wrapping_mul(q) == n { return true; }
247	                if q == hi { break; }
248	                q += 2;
249	            }
250	        }
251	        if p == hi { break; }
252	        p += 2;
253	    }
254	    false
255	}
256	
257	/// Solution-blind coupled trace: W_t = #{(low,high) local candidates that are
258	/// jointly extendable}. No true_pairs used. Returns (k, W_t, |M_t|, #low, #high).
259	pub fn coupled_trace(n: u64, m: u32) -> Vec<(u32, usize, u32)> {
260	    coupled_trace_detail(n, m).into_iter().map(|(k, w, mt, _, _)| (k, w, mt)).collect()
261	}
262	
263	pub fn coupled_trace_detail(n: u64, m: u32) -> Vec<(u32, usize, u32, usize, usize)> {
264	    let mut trace = Vec::new();
265	    for k in 0..=m {
266	        let l = k;
267	        let lows = low_candidates(n, k);
268	        let highs = high_candidates(n, m, l);
269	        let mut w = 0usize;
270	        for (pl, ql) in lows.iter() {
271	            for (ph, qh) in highs.iter() {
272	                if bridge_extendable(n, m, *pl, *ql, k, *ph, *qh, l) { w += 1; }
273	            }
274	        }
275	        let mt = 2 * m - k - l;
276	        trace.push((k, w, mt, lows.len(), highs.len()));
277	    }
278	    trace
279	}
280	
281	/// REPL: coupled_bridge bridge <N> <m> — run the coupled loop and report W_t.
282	pub fn repl_coupled_bridge(args: &[&str]) -> String {
283	    if args.is_empty() || args[0] == "help" {
284	        return String::from(
285	            "coupled_bridge bridge <N> <m> — bidirectional coupled reconstruction, W_t per step\n\
286	             e.g. coupled_bridge bridge 143 4",
287	        );
288	    }
289	    if args[0] != "bridge" || args.len() < 3 {
290	        return String::from("usage: coupled_bridge bridge <N> <m>");
291	    }
292	    let (n, m): (u64, u32) = match (args[1].parse(), args[2].parse()) {
293	        (Ok(a), Ok(b)) => (a, b),
294	        _ => return String::from("bad N/m"),
295	    };
296	    if m < 2 || m > 30 || n < 3 || n & 1 == 0 {
297	        return String::from("need odd N>=3, 2<=m<=30");
298	    }
299	    let detail = coupled_trace_detail(n, m);
300	    let sols = true_pairs(n, m);
301	    if sols.is_empty() && detail.iter().all(|(_, w, _, _, _)| *w == 0) {
302	        return format!("N={} m={}: no factor pairs (OPEN, no extension)", n, m);
303	    }
304	    let trace = coupled_trace_detail(n, m);
305	    let bounded = trace.iter().all(|(_, w, _, _, _)| *w <= sols.len().max(1));
306	    let mut out = format!(
307	        "coupled bridge: N={} m={} sols={:?} (|M|: {}->0)\n",
308	        n, m, sols, 2 * m
309	    );
310	    for (k, w, mt, nl, nh) in trace.iter() {
311	        out.push_str(&format!("  t k=l={} |M_t|={} W_t={} (#low={} #high={})\n", k, mt, w, nl, nh));
312	    }
313	    // Belnap reading: each surviving pair is a knowledge-join state;
314	    // conflicts (B) killed branches, unknowns (N) remain in M_t.
315	    out.push_str(&format!(
316	        "W_t bounded by #sols={}: {} (knowledge-join, conflicts killed)\nmu∘delta=id via bridge-coupled join: {}",
317	        sols.len(),
318	        if bounded { "PASS" } else { "FAIL" },
319	        if bounded { "CLOSED" } else { "OPEN" }
320	    ));
321	    out
322	}
323	
324	#[cfg(test)]
325	mod tests {
326	    use super::*;
327	    #[test]
328	    fn wt_stays_bounded_while_middle_shrinks() {
329	        for (n, m) in [(35u64, 3u32), (143, 4), (225, 4), (49, 3)] {
330	            let sols = true_pairs(n, m);
331	            assert!(!sols.is_empty());
332	            let tr = coupled_trace(n, m);
333	            assert_eq!(tr.len(), m as usize + 1);
334	            for (i, (k, w, mt)) in tr.iter().enumerate() {
335	                assert_eq!(*k, i as u32);
336	                assert!(*w <= sols.len());
337	                assert_eq!(*mt, 2 * m - 2 * i as u32);
338	            }
339	            assert_eq!(tr.last().unwrap().2, 0);
340	        }
341	    }
342	    #[test]
343	    fn bridge_kills_incompatible_pairs() {
344	        let low = LowState { p_low: 1, q_low: 1, k: 2, consistent_mod: true };
345	        let high = HighState { p_high: 3, q_high: 2, l: 2, consistent_prefix: true };
346	        // (11,13) at m=4: low(3,1)? no — (1,1) low bits of (11,13)=(3,1)&3=(3,1)≠(1,1)
347	        assert_eq!(bridge(143, 4, &low, &high, 11, 13), Bridge::LowConflict);
348	        let low2 = LowState { p_low: 3, q_low: 1, k: 2, consistent_mod: true };
349	        assert_eq!(bridge(143, 4, &low2, &high, 11, 13), Bridge::Consistent);
350	    }
351	}
