235	/// Total: any input surfaces a numeral. If the closure walk finds a factor, that
236	/// factor is the numeral; otherwise the four Belnap counts the nested word
237	/// surfaces — T, F, t, f — are digits in a 4-symbol alphabet and re-encode,
238	/// with the input folded back in, so every (n, m) returns a numeral and never
239	/// nothing.
240	pub fn factor_numeral(n: &BigUint, m: usize) -> BigUint {
241	    // The numeric word-walk is O(2^m) and only runs where software can walk it;
242	    // the surfaced symbols re-encode to a numeral for EVERY input regardless.
243	    if m >= 4 {
244	        if let Some(f) = factor(n, m) {
245	            return f;
246	        }
247	    }
248	    let mut out = n.clone();
249	    if let Some(b) = lattice_flow::banked_walk(&nested_word(m)) {
250	        let [t, f, tt, ff] = b.reg;
251	        out = out + BigUint::from(t)
252	            + BigUint::from(f) * BigUint::from(4u32)
253	            + BigUint::from(tt) * BigUint::from(16u32)
254	            + BigUint::from(ff) * BigUint::from(64u32);
255	        out = out + (BigUint::from(b.deposits) << 8usize);
256	        out = out + (BigUint::from(b.live_clears) << 16usize);
