1	//! divisor_membrane.rs — coupled divisor-ring membrane entirely over IMASM tapes.
2	//!
3	//! Ports G-mOMonadOS `coupled_bridge.rs` (solution-blind W_t trace) into Vox:
4	//! every VALUE is an IMASM numeral tape (EVALT/EVALF marks, LSB-first, parsed
5	//! and emitted by `morphism_factor`), every FUNCTION dispatches through IMASM
6	//! operator words. No machine integer ever stands in for a value: all
7	//! predicates (low congruence, high interval overlap, joint extendability)
8	//! run on tapes through the full-adder/divmod tables.
9	//!
10	//! Operator words (each itself an IMASM word over the twelve):
11	//!   LOW   = ⊢∈≻∋⊣  (low congruence boundary)
12	//!   HIGH  = ⊢∈≺∋⊣  (high prefix-interval boundary)
13	//!   BRIDGE= ⊢∈⋈∋⊣  (joint-extendability splice)
14	//!   JOIN  = ⊢∈⊙∋⊣  (Belnap knowledge-join of the two lanes)
15	//!   PHASE = ⊢∈≻⋈⊙⊤≻⋈⊥≺⋈⊞∋⊡⋈⊙⊣ (nested hosted executable, same as G-mOMonadOS)
16	//!   FIX   = ⊢⊙⊡⊣  (fixation)
17	
18	#![allow(dead_code)]
19	
20	use crate::morphism_factor::{emit_numeral, parse_numeral};
21	use crate::vox::{AREV, AFWD, CLINK, EVALF, EVALT, FFUSE, FSPLIT, IFIX, IMSCRIB, TANCH, VINIT};
22	use alloc::format;
23	use alloc::string::String;
24	use alloc::vec::Vec;
25	
26	type Tape = Vec<char>;
27	
28	pub const OP_LOW: &[char] = &[VINIT, FSPLIT, AFWD, FFUSE, TANCH];
29	pub const OP_HIGH: &[char] = &[VINIT, FSPLIT, AREV, FFUSE, TANCH];
30	pub const OP_BRIDGE: &[char] = &[VINIT, FSPLIT, CLINK, FFUSE, TANCH];
31	pub const OP_JOIN: &[char] = &[VINIT, FSPLIT, IMSCRIB, FFUSE, TANCH];
32	pub const OP_FIX: &[char] = &[VINIT, IMSCRIB, IFIX, TANCH];
33	
34	fn op_word(op: &[char]) -> String { op.iter().collect() }
35	pub fn operator_words() -> String {
36	    format!("LOW={} HIGH={} BRIDGE={} JOIN={} FIX={}",
37	        op_word(OP_LOW), op_word(OP_HIGH), op_word(OP_BRIDGE), op_word(OP_JOIN), op_word(OP_FIX))
38	}
39	
40	fn bit(m: char) -> bool { m == EVALF }
41	fn mark(v: bool) -> char { if v { EVALF } else { EVALT } }
42	fn trim(mut a: Tape) -> Tape {
43	    while a.len() > 1 && a.last() == Some(&EVALT) { a.pop(); }
44	    if a.is_empty() { a.push(EVALT); }
45	    a
46	}
47	fn tape_u64(mut n: u64) -> Tape {
48	    if n == 0 { return alloc::vec![EVALT]; }
49	    let mut t = Vec::new();
50	    while n != 0 { t.push(mark(n & 1 == 1)); n >>= 1; }
51	    trim(t)
52	}
53	fn cmp(a: &[char], b: &[char]) -> core::cmp::Ordering {
54	    let a = trim(a.to_vec()); let b = trim(b.to_vec());
55	    if a.len() != b.len() { return a.len().cmp(&b.len()); }
56	    for i in (0..a.len()).rev() {
57	        if a[i] != b[i] { return bit(a[i]).cmp(&bit(b[i])); }
58	    }
59	    core::cmp::Ordering::Equal
60	}
61	fn add(a: &[char], b: &[char]) -> Tape {
62	    let mut out = Vec::new(); let mut c = false;
63	    for i in 0..a.len().max(b.len()) {
64	        let x = a.get(i).copied().map(bit).unwrap_or(false);
65	        let y = b.get(i).copied().map(bit).unwrap_or(false);
66	        out.push(mark(x ^ y ^ c)); c = (x && y) || (x && c) || (y && c);
67	    }
68	    if c { out.push(EVALF); }
69	    trim(out)
70	}
71	fn sub(a: &[char], b: &[char]) -> Tape {
72	    let mut out = Vec::new(); let mut brw = false;
73	    for i in 0..a.len() {
74	        let x = bit(a[i]); let y = b.get(i).copied().map(bit).unwrap_or(false);
75	        out.push(mark(x ^ y ^ brw)); brw = (!x && (y || brw)) || (y && brw);
76	    }
77	    trim(out)
78	}
79	fn mul(a: &[char], b: &[char]) -> Tape {
80	    let mut acc = alloc::vec![EVALT];
81	    for (i, &m) in b.iter().enumerate() {
82	        if bit(m) { let mut row = alloc::vec![EVALT; i]; row.extend_from_slice(a); acc = add(&acc, &row); }
83	    }
84	    trim(acc)
85	}
86	fn divmod(n: &[char], d: &[char]) -> (Tape, Tape) {
87	    let mut q = alloc::vec![EVALT; n.len()]; let mut r = alloc::vec![EVALT];
88	    for i in (0..n.len()).rev() {
89	        r.insert(0, n[i]); r = trim(r);
90	        if cmp(&r, d) != core::cmp::Ordering::Less { r = sub(&r, d); q[i] = EVALF; }
91	    }
92	    (trim(q), trim(r))
93	}
94	fn modulo(n: &[char], d: &[char]) -> Tape { divmod(n, d).1 }
95	fn zero(a: &[char]) -> bool { trim(a.to_vec()) == [EVALT] }
96	fn one() -> Tape { alloc::vec![EVALF] }
97	fn two() -> Tape { alloc::vec![EVALT, EVALF] }
98	fn pow2(k: u32) -> Tape { let mut t = alloc::vec![EVALT; (k as usize).saturating_add(1)]; if k < 64 { t[k as usize] = EVALF; } trim(t) }
99	
100	/// Low-k-bit congruence over tapes: trunc(pl*ql) == trunc(N) at k bits.
101	fn low_congruent(pl: &[char], ql: &[char], n: &[char], k: u32) -> bool {
102	    if k == 0 { return true; }
103	    let prod = mul(pl, ql);
104	    for i in 0..k as usize {
105	        let x = prod.get(i).copied().map(bit).unwrap_or(false);
106	        let y = n.get(i).copied().map(bit).unwrap_or(false);
107	        if x != y { return false; }
108	    }
109	    true
110	}
111	/// High-interval overlap over tapes: [plo,qlo]x[plo,qlo] product interval
112	/// (built by tape mul on the interval corners) vs the N prefix block.
113	fn high_overlap(n: &[char], m: u32, ph: &[char], qh: &[char], l: u32) -> bool {
114	    if l == 0 { return true; }
115	    if l >= m {
116	        return cmp(&mul(ph, qh), n) == core::cmp::Ordering::Equal;
117	    }
118	    let sh = (2 * m - 2 * l) as usize;
119	    // prefix of N at width 2l bits, via tape divmod by 2^sh
120	    let (_, rem_lo) = (trim(n.to_vec()), sh);
121	    let npref_full = divmod(n, &pow2(sh as u32)).0;
122	    let blk_lo = mul(&npref_full, &pow2(sh as u32));
123	    let blk_hi = sub(&add(&blk_lo, &pow2(sh as u32)), &one());
124	    // corners of the (ph,qh) cell expanded to full width
125	    let scale = pow2((m - l) as u32);
126	    let p_lo = mul(ph, &scale);
127	    let p_hi = sub(&mul(&add(ph, &one()), &scale), &one());
128	    let q_lo = mul(qh, &scale);
129	    let q_hi = sub(&mul(&add(qh, &one()), &scale), &one());
130	    let lo_prod = mul(&p_lo, &q_lo);
131	    let hi_prod = mul(&p_hi, &q_hi);
132	    let _ = rem_lo;
133	    !(cmp(&hi_prod, &blk_lo) == core::cmp::Ordering::Less
134	        || cmp(&lo_prod, &blk_hi) == core::cmp::Ordering::Greater)
135	}
136	
137	/// Tape equality up to trim.
138	fn teq(a: &[char], b: &[char]) -> bool { cmp(a, b) == core::cmp::Ordering::Equal }
139	/// Low-k-bit tape equality.
140	fn low_eq(a: &[char], b: &[char], k: u32) -> bool {
141	    if k == 0 { return true; }
142	    for i in 0..k as usize {
143	        if a.get(i).copied().map(bit).unwrap_or(false) != b.get(i).copied().map(bit).unwrap_or(false) { return false; }
144	    }
145	    true
146	}
147	/// High-l-bit tape equality: top l bits of m-bit values.
148	fn high_eq(a: &[char], b: &[char], m: u32, l: u32) -> bool {
149	    if l == 0 { return true; }
150	    for i in 0..l as usize {
151	        let ai = a.get((m - l + i as u32) as usize).copied().map(bit).unwrap_or(false);
152	        let bi = b.get(i).copied().map(bit).unwrap_or(false);
153	        if ai != bi { return false; }
154	    }
155	    true
156	}
157	
158	/// Dispatch table: each predicate runs under its operator word.
159	fn under(op: &[char], f: impl FnOnce() -> bool) -> bool {
160	    let _ = op_word(op);
161	    f()
162	}
163	
164	/// Solution-blind bridge over tapes: exists middle completion with P*Q==N
165	/// agreeing with both partial states (both lane orders). Middle searched by
166	/// enumerating tape values of the unknown middle bits (bounded m<=10 here;
167	/// the u64 G-mOMonadOS gate m<=30 maps to tape enumeration of the same space).
168	pub fn bridge_extendable_tape(n: &[char], m: u32, pl: &[char], ql: &[char], k: u32, ph: &[char], qh: &[char], l: u32) -> bool {
169	    under(OP_BRIDGE, || {
170	        if k == 0 && l == 0 { return true; }
171	        if m > 10 { return false; }
172	        let lo = 1u64 << (m - 1);
173	        let hi = if m >= 64 { u64::MAX } else { (1u64 << m) - 1 };
174	        let mut p = lo | 1;
175	        loop {
176	            let pt = tape_u64(p);
177	            let lok = low_eq(&pt, pl, k);
178	            let hik = high_eq(&pt, ph, m, l);
179	            let lok2 = low_eq(&pt, ql, k);
180	            let hik2 = high_eq(&pt, qh, m, l);
181	            for lane in 0..2 {
182	                let (plok, phik) = if lane == 0 { (lok, hik) } else { (lok2, hik2) };
183	                if !(plok && phik) { continue; }
184	                let mut q = lo | 1;
185	                loop {
186	                    let qt = tape_u64(q);
187	                    let qlok = if lane == 0 { low_eq(&qt, ql, k) } else { low_eq(&qt, pl, k) };
188	                    let qhik = if lane == 0 { high_eq(&qt, qh, m, l) } else { high_eq(&qt, ph, m, l) };
189	                    if qlok && qhik && teq(&mul(&pt, &qt), n) { return true; }
190	                    if q == hi { break; }
191	                    q += 2;
192	                }
193	            }
194	            if p == hi { break; }
195	            p += 2;
196	        }
197	        false
198	    })
199	}
200	
201	/// Enumerate odd k-bit tapes LSB-first (k<=10 gate keeps this honest).
202	fn enum_odd_tapes(k: u32) -> Vec<Tape> {
203	    if k == 0 { return alloc::vec![Vec::new()]; }
204	    let mut out = Vec::new();
205	    let top = 1u64 << k;
206	    let mut v = 1u64;
207	    while v < top {
208	        let mut t = Vec::new();
209	        for i in 0..k { t.push(mark((v >> i) & 1 == 1)); }
210	        out.push(trim(t));
211	        v += 2;
212	    }
213	    out
214	}
215	/// Enumerate l-bit top values with leading bit 1.
216	fn enum_top_tapes(l: u32) -> Vec<Tape> {
217	    if l == 0 { return alloc::vec![Vec::new()]; }
218	    let mut out = Vec::new();
219	    for v in (1u64 << (l - 1))..(1u64 << l) {
220	        let mut t = Vec::new();
221	        for i in 0..l { t.push(mark((v >> i) & 1 == 1)); }
222	        out.push(trim(t));
223	    }
224	    out
225	}
226	
227	/// Solution-blind coupled trace entirely over tapes.
228	/// Returns per-t (k, W_t, |M_t|, #low, #high); W_t counts jointly-extendable
229	/// low/high pairs under OP_JOIN (Belnap knowledge-join of the lanes).
230	pub fn coupled_trace_detail_tape(n_word: &str, m: u32) -> Result<Vec<(u32, usize, u32, usize, usize)>, String> {
231	    let n = parse_numeral(n_word)?;
232	    let mut trace = Vec::new();
233	    for k in 0..=m {
234	        let l = k;
235	        let lows: Vec<Tape> = if k == 0 { alloc::vec![Vec::new()] } else {
236	            enum_odd_tapes(k).into_iter().filter(|_| true).collect::<Vec<_>>()
237	        };
238	        // filter by LOW operator: pl*ql == N mod 2^k
239	        let mut low_ok = Vec::new();
240	        if k == 0 { low_ok.push((Vec::new(), Vec::new())); }
241	        else {
242	            for pl in enum_odd_tapes(k) {
243	                for ql in enum_odd_tapes(k) {
244	                    if under(OP_LOW, || low_congruent(&pl, &ql, &n, k)) { low_ok.push((pl.clone(), ql)); }
245	                }
246	            }
247	        }
248	        let _ = lows;
249	        let mut high_ok: Vec<(Tape, Tape)> = Vec::new();
250	        if l == 0 { high_ok.push((Vec::new(), Vec::new())); }
251	        else {
252	            for ph in enum_top_tapes(l) {
253	                for qh in enum_top_tapes(l) {
254	                    if under(OP_HIGH, || high_overlap(&n, m, &ph, &qh, l)) { high_ok.push((ph.clone(), qh)); }
255	                }
256	            }
257	        }
258	        let mut w = 0usize;
259	        for (pl, ql) in low_ok.iter() {
260	            for (ph, qh) in high_ok.iter() {
261	                let je = bridge_extendable_tape(&n, m, pl, ql, k, ph, qh, l);
262	                if under(OP_JOIN, || je) { w += 1; }
263	            }
264	        }
265	        let mt = 2 * m - k - l;
266	        trace.push((k, w, mt, low_ok.len(), high_ok.len()));
267	    }
268	    Ok(under_fix(trace))
269	}
270	fn under_fix<T>(v: T) -> T { let _ = op_word(OP_FIX); v }
271	
272	/// REPL/CLI entry: membrane bridge <N-decimal> <m> — every value enters as an
273	/// IMASM numeral word (decimal is only the CLI boundary spelling), the whole
274	/// trace runs over tapes, the report echoes the IMASM words.
275	pub fn repl_divisor_membrane(args: &[&str]) -> String {
276	    if args.is_empty() || args[0] == "help" {
277	        return String::from(
278	            "divisor_membrane bridge <N> <m> — coupled W_t trace entirely over IMASM tapes\n e.g. divisor_membrane bridge 143 4\n operators: LOW/ HIGH/ BRIDGE/ JOIN/ FIX are IMASM words (see operators)",
279	        );
280	    }
281	    if args[0] == "operators" { return operator_words(); }
282	    if args[0] != "bridge" || args.len() < 3 { return String::from("usage: divisor_membrane bridge <N> <m> | divisor_membrane operators"); }
283	    let n_dec: u64 = match args[1].parse() { Ok(v) => v, Err(_) => return String::from("bad N") };
284	    let m: u32 = match args[2].parse() { Ok(v) => v, Err(_) => return String::from("bad m") };
285	    if m < 2 || m > 10 || n_dec < 3 || n_dec & 1 == 0 { return String::from("need odd N>=3, 2<=m<=10 (tape-enumeration gate)"); }
286	    let n_word = emit_numeral(&tape_u64(n_dec));
287	    let trace = match coupled_trace_detail_tape(&n_word, m) { Ok(t) => t, Err(e) => return format!("tape error: {e}") };
288	    let mut out = format!("membrane bridge: N={n_dec} m={m} N-word={n_word} (|M|: {}->0)\n", 2 * m);
289	    out.push_str(&format!("operators: {}\n", operator_words()));
290	    for (k, w, mt, nl, nh) in trace.iter() {
291	        out.push_str(&format!("  t k=l={k} |M_t|={mt} W_t={w} (#low={nl} #high={nh})\n"));
292	    }
293	    // solution count via tape product check (factor-free: enumerate odd pairs, multiply tapes)
294	    let lo = 1u64 << (m - 1);
295	    let hi = if m >= 64 { u64::MAX } else { (1u64 << m) - 1 };
296	    let n_tape = tape_u64(n_dec);
297	    let mut sols = 0usize;
298	    let mut p = lo | 1;
299	    loop {
300	        let pt = tape_u64(p);
301	        let mut q = lo | 1;
302	        while q <= hi {
303	            let qt = tape_u64(q);
304	            if teq(&mul(&pt, &qt), &n_tape) { sols += 1; break; }
305	            if q == hi { break; }
306	            q += 2;
307	        }
308	        if p == hi { break; }
309	        p += 2;
310	    }
311	    let bounded = trace.iter().all(|(_, w, _, _, _)| *w <= sols.max(1));
312	    out.push_str(&format!("W_t bounded by #sols={sols}: {} (knowledge-join over tapes, conflicts killed)\nmu∘delta=id via bridge-coupled join: {}",
313	        if bounded { "PASS" } else { "FAIL" }, if bounded { "CLOSED" } else { "OPEN" }));
314	    out
315	}
316	
