318	mod tests {
319	    use super::*;
320	    #[test]
321	    fn membrane_143_closes_over_tapes() {
322	        let w = emit_numeral(&tape_u64(143));
323	        let tr = coupled_trace_detail_tape(&w, 4).unwrap();
324	        assert_eq!(tr.len(), 5);
325	        for (i, (k, _, mt, _, _)) in tr.iter().enumerate() {
326	            assert_eq!(*k, i as u32);
327	            assert_eq!(*mt, 8 - 2 * i as u32);
328	        }
329	        assert_eq!(tr.last().unwrap().2, 0);
330	        assert!(tr.iter().all(|(_, w, _, _, _)| *w <= 2));
331	    }
332	    #[test]
333	    fn membrane_35_closes_over_tapes() {
334	        let w = emit_numeral(&tape_u64(35));
335	        let tr = coupled_trace_detail_tape(&w, 3).unwrap();
336	        assert!(tr.iter().all(|(_, w, _, _, _)| *w <= 2));
337	        assert_eq!(tr.last().unwrap().2, 0);
338	    }
339	    #[test]
340	    fn operators_are_imasm_words() {
341	        for op in [OP_LOW, OP_HIGH, OP_BRIDGE, OP_JOIN, OP_FIX] {
342	            assert_eq!(op.first(), Some(&VINIT));
343	            assert_eq!(op.last(), Some(&TANCH));
344	        }
345	    }
