        let n2 = &p2 * &q2;
        let f2 = closure_height_walk(&n2, m2, 256).unwrap();
        assert!(f2 == p2 || f2 == q2, "must recover one factor at m=82");
        assert_eq!(&f2 * (&n2 / &f2), n2, "m=82 factor must close N");
