    // 2^(m-3), held in BigUint, never a `usize` shift — capping it at the
    // platform's word width and calling the excess "infeasible" mistook a
    // register-width artifact for a property of the tiling. But an unbounded
    // tiling still needs a real, explicit, caller-stated search budget
    // (`max_steps`, same contract as `closure_height_walk`) or a width like
    // m=431 turns "infeasible at this width" into a genuine 2^428-iteration
    // walk that never returns.
    let positions = BigUint::one() << (m - 3);
