pub fn factor(n: &BigUint, m: usize, max_steps: usize) -> Option<BigUint> {
    if m < 4 { return None; }
    let n_wt = WordTape::from_biguint(n);
    let nine = WordTape::from_small(9);
    let inv9 = inv_mod_pow2(&nine, m);
    let nm = n_wt.truncate(m);
    let lead = pow2(m - 1);
    let mask = pow2(m).sub(&WordTape::one()).unwrap();
    let m3 = mask.sub(&WordTape::from_small(2)).unwrap();
    let reps: [WordTape; 4] = [
        WordTape::from_small(1),
        WordTape::from_small(3),
        mask,
        m3,
    ];
    // The register is a torus, not a machine word: position count is the true
    // 2^(m-3), held in BigUint, never a `usize` shift — capping it at the
    // platform's word width and calling the excess "infeasible" mistook a
    // register-width artifact for a property of the tiling. But an unbounded
    // tiling still needs a real, explicit, caller-stated search budget
    // (`max_steps`, same contract as `closure_height_walk`) or a width like
    // m=431 turns "infeasible at this width" into a genuine 2^428-iteration
    // walk that never returns.
    let positions = BigUint::one() << (m - 3);
    let max_steps_big = BigUint::from(max_steps);
    let steps = if positions < max_steps_big { positions.to_usize().unwrap() } else { max_steps };
    for s in reps.iter() {
        let mut p: WordTape = s.truncate(m);
        let mut q: WordTape = nm.mul(&inv_mod_pow2(&p, m)).truncate(m);
        for _ in 0..steps {
            if p.ge(&lead) && q.ge(&lead) && p.mul(&q) == n_wt {
                let f = if q.ge(&p) { &p } else { &q };
                return Some(f.to_biguint());
            }
            p = p.mul(&nine).truncate(m);
            q = q.mul(&inv9).truncate(m);
        }
    }
    None
}

