78	    // coset, so its cost is inherent to the search, not the register. Past
79	    // the walk floor it is not a search worth starting; `factor_symbolic`'s
80	    // own tests already name this threshold as "the m<=26 walk floor."
81	    if m < 4 || m > 26 { return None; }
82	    let n_wt = WordTape::from_biguint(n);
83	    let nine = WordTape::from_small(9);
84	    let inv9 = inv_mod_pow2(&nine, m);
85	    let nm = n_wt.truncate(m);
86	    let lead = pow2(m - 1);
87	    let mask = pow2(m).sub(&WordTape::one()).unwrap();
88	    let m3 = mask.sub(&WordTape::from_small(2)).unwrap();
89	    let reps: [WordTape; 4] = [
90	        WordTape::from_small(1),
91	        WordTape::from_small(3),
92	        mask,
93	        m3,
94	    ];
95	    let positions = 1usize << (m - 3);
96	    for s in reps.iter() {
97	        let mut p: WordTape = s.truncate(m);
98	        let mut q: WordTape = nm.mul(&inv_mod_pow2(&p, m)).truncate(m);
99	        for _ in 0..positions {
100	            if p.ge(&lead) && q.ge(&lead) && p.mul(&q) == n_wt {
101	                let f = if q.ge(&p) { &p } else { &q };
102	                return Some(f.to_biguint());
103	            }
104	            p = p.mul(&nine).truncate(m);
105	            q = q.mul(&inv9).truncate(m);
106	        }
107	    }
108	    None
109	}
