2198	    n: &BigInt,
2199	    p_bits: usize,
2200	    q_bits: usize,
2201	    k: usize,
2202	    p_val: BigUint,
2203	    q_val: BigUint,
2204	    c: BigInt,
2205	    budget: &mut UnbraidBudget,
2206	    stop: &core::sync::atomic::AtomicBool,
2207	) -> Option<(BigUint, BigUint)> {
2208	    budget.nodes += 1;
2209	    if budget.nodes > budget.cap || stop.load(core::sync::atomic::Ordering::Relaxed) {
2210	        return None;
2211	    }
2212	    let short = p_bits.min(q_bits);
2213	    let long = p_bits.max(q_bits);
2214	    if k == long {
2215	        // c==0 is proven to mean p*q==N exactly whenever the recursion's
2216	        // own exactness invariant held at every step -- but that proof
2217	        // assumes N odd, and the N=100 false positive showed what happens
2218	        // when a caller hands this an N where the seed carry was never a
