                } else if awaiting_bigint_arg(t) {
                    bigint_cont = Some(t.to_string());
                    continue;
                } else {
                    t.to_string()
                }
            }
        };
        let line = line_owned.as_str();
        let _vessel = crate::runtime_nesting::CommandVessel::admit(line);

        // Multi-line ask paste: accumulate until a lone `.`
