            cmd if cmd.starts_with(":") => {
                if let Ok(n) = cmd[1..].parse::<u8>() {
                    if let Some(cat) = fkey_to_category(n) {
                        if enter_context(&mut ctx_stack, cat) {
                            if let Some(ctx) = ctx_stack.current() {
                                print_help_topic(ctx.name);
                            }
                        }
