pub fn winding(n: &str, a_opt: Option<u64>) -> String {
    use crate::native_numeral::{add_via_word, divmod_via_word, mod_pow_walk, modulo_via_word, subtract_via_word, to_bits_low_first};
    let t = n.trim();
    let nv: BigUint = match t.parse() {
        Ok(v) => v,
        Err(_) => return format!("trilattice_factor winding {}: not a non-negative integer", n),
    };
    let two = BigUint::from(2u32);
    if nv < two {
        return format!("trilattice_factor winding {}: n < 2, no winding", n);
    }
    if modulo_via_word(&nv, &two).unwrap().is_zero() {
        return format!(
            "trilattice_factor winding {}: {} = 2 × {}   (even, split before any winding)",
            n, nv, divmod_via_word(&nv, &two).unwrap().0
        );
    }

    let bases: alloc::vec::Vec<BigUint> = match a_opt {
        Some(a) => alloc::vec![BigUint::from(a)],
        None => WINDING_BASES.iter().map(|&a| BigUint::from(a)).collect(),
    };

    let one = BigUint::one();
    let mut o = format!("trilattice_factor winding {}:\n", n);
    let mut budget_hit = false;
    for a in bases.iter() {
        let a = modulo_via_word(a, &nv).unwrap();
        if a < two { continue; }
        let g = big_gcd(a.clone(), nv.clone());
        if g > one {
            o.push_str(&format!(
                "  base {} shares a factor: gcd = {} → {} = {} × {}",
                a, g, nv, g, divmod_via_word(&nv, &g).unwrap().0
            ));
            return o;
        }
        let d = match order_multiple_leaping(&a, &nv, LEAP_STEPS) {
            Some(d) => d,
            None => { budget_hit = true; continue; }
        };
        // d is a multiple of the order (a crossing gives a^{d} = 1). Halve while
        // a^{d/2} = 1, keeping it a multiple, until a^{d/2} is a nontrivial
        // square root of 1 that splits n.
        let mut r = d.clone();
        while modulo_via_word(&r, &two).unwrap().is_zero() {
            let half = divmod_via_word(&r, &two).unwrap().0;
            let a_half = mod_pow_walk(&a, &to_bits_low_first(&half), &nv);
            if a_half == one { r = half; continue; }   // still a multiple, reduce
            if a_half == subtract_via_word(&nv, &one).unwrap() { break; }          // trivial root, this base fails
            let p = big_gcd(subtract_via_word(&a_half, &one).unwrap(), nv.clone());
            let q = big_gcd(add_via_word(&a_half, &one), nv.clone());
            let nontrivial = p > one && q > one && p < nv && q < nv;
            if nontrivial {
                o.push_str(&format!(
                    "  base {}: winding r = {} (a ROTAT period of {} mod {}, from a leaper crossing)\n",
                    a, r, a, nv
                ));
                o.push_str(&format!(
                    "  winding fixed as its native numeral (⊡ immutable_record): {}\n",
                    native_encode(&r.to_str_radix(10))
                ));
                o.push_str(&format!(
                    "  ⊡ ZWIND holonomy: ∮ A = 2π·{}, the integer winding of the orbit loop\n",
                    r
                ));
                let (lo, hi) = if p <= q { (p, q) } else { (q, p) };
                o.push_str(&format!(
                    "  a^(r/2) ± 1 splits it: {} = {} × {}   read off the winding, no table",
                    nv, lo, hi
                ));
                return o;
            }
            break;
        }
    }
    if budget_hit {
        o.push_str(&format!(
            "  no leaper crossing within the walk budget; hand to `trilattice_factor factor {}`",
            n
        ));
    } else {
        o.push_str(&format!(
            "  no base in the set gave an even winding with a non-trivial split; hand to `trilattice_factor factor {}`",
            n
        ));
    }
    o
}

